    // 计算斐波那契数列第 n 项
    return 0;
}

solution_code:
int fibonacci(int n) {
    if (n <= 2) return 1;
    int a = 1, b = 1, c;
    for (int i = 3; i <= n; i++) {
        c = a + b;
        a = b;
        b = c;
    }
    return b;
}
